import { randomUUID } from "node:crypto";
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import {
  saveTemplate,
  archiveTemplate,
  chooseFreeTemplate,
  saveContact,
  savePreferences,
  importContacts,
  addContactToShortlist,
  addToShortlist,
  submitCampaign,
} from "@/lib/actions";
import { markReplied, undoReply } from "@/lib/recipient-actions";
import { saveFollowUpDays } from "@/lib/launch-actions";
import { readFollowUps } from "@/lib/follow-ups";
import { clearCompletedHistory } from "@/lib/history";
import { listCustomRoles } from "@/lib/role-store";
import { createCampaign } from "@/lib/campaigns";
import { deliverOne } from "@/lib/inngest";
import { dispatchUsagePending } from "@/lib/usage-reconciliation";
import {
  claimUsage,
  importUsageEvidence,
  withUsageTransaction,
} from "@/lib/usage-ledger";
import { resolveUsagePeriods } from "@/lib/usage-periods";
import { GET as exportTemplate } from "@/app/api/templates/[id]/export/route";

const fields = {
  name: "Introduction",
  subject: "Hi {{name}}",
  body: "Applying for {{role}}",
};
function form(values: Record<string, string>) {
  const data = new FormData();
  for (const [key, value] of Object.entries(values)) data.set(key, value);
  return data;
}
describe.runIf(databaseTestsEnabled)("authenticated feature policy", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
  });
  beforeEach(async () => {
    await setGating(boundary.db, true);
    boundary.send.mockReset().mockResolvedValue({ data: { id: "accepted" } });
    boundary.gmail.mockReset().mockResolvedValue({
      email: "[REDACTED_EMAIL]",
      name: "Fixture",
      gmail: { users: { messages: { send: boundary.send } } },
    });
  });
  afterAll(async () => {
    if (fixture) await fixture.close();
  });
  async function owner(paid = false) {
    const f = await usageOwner(boundary.db, { paid });
    // Deliberately stale session plan cannot grant authorization.
    boundary.user.mockResolvedValue({
      id: f.user.id,
      plan: "PAID",
      isAdmin: true,
    });
    boundary.auth.mockResolvedValue({ user: { id: f.user.id } });
    return f;
  }
  async function downgrade(userId: string) {
    await boundary.db.user.update({
      where: { id: userId },
      data: { plan: "FREE", subscriptionStatus: "EXPIRED" },
    });
  }
  it("serializes concurrent Free template creation and maintains an eligible fallback after archive", async () => {
    const f = await owner();
    await archiveTemplate(f.template.id);
    const results = await Promise.all(
      Array.from({ length: 8 }, () => saveTemplate(form(fields))),
    );
    expect(results.filter((result) => result.ok)).toHaveLength(1);
    expect(
      results.filter((result) => result.code === "UPGRADE_REQUIRED"),
    ).toHaveLength(7);
    const active = await boundary.db.template.findFirstOrThrow({
      where: { userId: f.user.id, archivedAt: null },
    });
    expect(
      await boundary.db.user.findUnique({ where: { id: f.user.id } }),
    ).toMatchObject({ freeTemplateId: active.id });
    expect(
      (await saveTemplate(form({ ...fields, id: active.id, body: "Updated" })))
        .ok,
    ).toBe(true);
  });
  it("retains complete templates on downgrade, permits switching and export, and unlocks on upgrade", async () => {
    const f = await owner(true);
    expect(
      (
        await saveTemplate(
          form({ ...fields, name: "Extra", body: "Retained full content" }),
        )
      ).ok,
    ).toBe(true);
    const extra = await boundary.db.template.findFirstOrThrow({
      where: { userId: f.user.id, name: "Extra" },
    });
    await downgrade(f.user.id);
    expect(await saveTemplate(form({ ...fields, id: extra.id }))).toMatchObject(
      { ok: false, code: "UPGRADE_REQUIRED" },
    );
    const input = await f.input();
    await expect(
      createCampaign(f.user.id, { ...input, templateId: extra.id }),
    ).rejects.toMatchObject({ code: "UPGRADE_REQUIRED" });
    const response = await exportTemplate(new Request("http://localhost"), {
      params: Promise.resolve({ id: extra.id }),
    });
    expect(response.headers.get("Content-Disposition")).toContain("attachment");
    expect(response.headers.get("Cache-Control")).toBe("private, no-store");
    expect(await response.json()).toMatchObject({
      body: "Retained full content",
    });
    expect((await chooseFreeTemplate(extra.id)).ok).toBe(true);
    expect((await saveTemplate(form({ ...fields, id: extra.id }))).ok).toBe(
      true,
    );
    expect(
      await saveTemplate(form({ ...fields, id: f.template.id })),
    ).toMatchObject({ code: "UPGRADE_REQUIRED" });
    await archiveTemplate(extra.id);
    expect(
      await boundary.db.user.findUnique({ where: { id: f.user.id } }),
    ).toMatchObject({ freeTemplateId: f.template.id });
    expect((await chooseFreeTemplate(extra.id)).ok).toBe(false);
    expect((await chooseFreeTemplate("invalid")).ok).toBe(false);
    const other = await usageOwner(boundary.db);
    expect((await chooseFreeTemplate(other.template.id)).ok).toBe(false);
    expect(
      (
        await exportTemplate(new Request("http://localhost"), {
          params: Promise.resolve({ id: other.template.id }),
        })
      ).status,
    ).toBe(404);
    await boundary.db.user.update({
      where: { id: f.user.id },
      data: { plan: "PAID", subscriptionStatus: "ACTIVE" },
    });
    expect((await saveTemplate(form(fields))).ok).toBe(true);
    boundary.auth.mockResolvedValue(null);
    expect(
      (
        await exportTemplate(new Request("http://localhost"), {
          params: Promise.resolve({ id: f.template.id }),
        })
      ).status,
    ).toBe(401);
  });
  it.each(["FREE", "PAID", "LEGACY"])(
    "enforces campaign caps and gates direct actions for %s",
    async (mode) => {
      const f = await owner(mode === "PAID");
      if (mode === "LEGACY") await setGating(boundary.db, false);
      const cap = mode === "FREE" ? 3 : 10;
      await expect(
        createCampaign(f.user.id, await f.input(cap + 1)),
      ).rejects.toBeDefined();
      const input = await f.input(cap);
      const a = await createCampaign(f.user.id, input);
      const b = await createCampaign(f.user.id, input);
      expect(a).toMatchObject({ id: b.id, count: cap });
      expect(
        await boundary.db.usageReservation.count({
          where: { userId: f.user.id },
        }),
      ).toBe(cap);
      const csv = "name,email,jobRole\nAda,[REDACTED_EMAIL],Software Engineer";
      expect((await importContacts(csv)).ok).toBe(mode !== "FREE");
      expect(
        (
          await saveContact(
            form({
              name: "Custom",
              email: `${randomUUID()}@example.test`,
              jobRole: "Research Engineer",
            }),
          )
        ).ok,
      ).toBe(true);
      expect(
        (await savePreferences({ preferredRoles: ["Research Engineer"] })).ok,
      ).toBe(true);
      expect((await saveFollowUpDays(3)).ok).toBe(mode !== "FREE");
      expect((await saveFollowUpDays(0)).ok).toBe(true);
      expect((await saveFollowUpDays(5)).ok).toBe(false);
    },
  );
  it.each([false, true])(
    "allows arbitrary contact roles independently of shortcuts (paid=%s)",
    async (paid) => {
      const f = await owner(paid);
      const shortcuts = Array.from(
        { length: paid ? 8 : 2 },
        (_, i) => `Shortcut ${i}`,
      );
      expect((await savePreferences({ preferredRoles: shortcuts })).ok).toBe(
        true,
      );
      for (let i = 0; i < 4; i++) {
        expect(
          (
            await saveContact(
              form({
                name: "Ada",
                email: `role${i}@example.test`,
                jobRole: `Arbitrary role ${i}`,
              }),
            )
          ).ok,
        ).toBe(true);
      }
      const contact = await boundary.db.contact.findFirstOrThrow({
        where: { userId: f.user.id },
      });
      expect(
        (
          await saveContact(
            form({
              id: contact.id,
              name: contact.name,
              email: contact.email,
              jobRole: "Changed role",
            }),
          )
        ).ok,
      ).toBe(true);
      expect(
        (await savePreferences({ preferredRoles: [...shortcuts, "Extra"] })).ok,
      ).toBe(false);
      expect((await savePreferences({ preferredRoles: [] })).ok).toBe(true);
      expect(
        (await savePreferences({ preferredRoles: ["New shortcut"] })).ok,
      ).toBe(true);
      expect(
        (await savePreferences({ preferredRoles: ["Engineer", " ENGINEER "] }))
          .ok,
      ).toBe(false);
    },
  );
  it("preserves legacy shortcuts and permits removal after downgrade", async () => {
    const f = await owner(true);
    const roles = Array.from({ length: 20 }, (_, i) => `Legacy ${i}`);
    await boundary.db.user.update({
      where: { id: f.user.id },
      data: { preferredRoles: roles },
    });
    expect((await savePreferences({ preferredRoles: roles })).ok).toBe(true);
    await downgrade(f.user.id);
    expect(
      (await savePreferences({ preferredRoles: roles.slice(0, 19) })).ok,
    ).toBe(true);
    expect(
      (
        await savePreferences({
          preferredRoles: [...roles.slice(0, 18), "Replacement"],
        })
      ).ok,
    ).toBe(false);
    expect(
      (await savePreferences({ preferredRoles: ["Replacement", "Designer"] }))
        .ok,
    ).toBe(true);
  });
  it.each([true, false])(
    "rejects Free Compose overrides even with gating=%s and stale paid sessions",
    async (gating) => {
      const f = await owner();
      await setGating(boundary.db, gating);
      const input = await f.input(2);
      await boundary.db.contact.update({
        where: { id: input.recipientIds[0], userId: f.user.id },
        data: { jobRole: "  Researcher  " },
      });
      await expect(
        createCampaign(f.user.id, {
          ...input,
          recipientRoles: { [input.recipientIds[0]]: "Other role" },
        }),
      ).rejects.toMatchObject({
        field: "role",
        message: expect.stringContaining("requires Premium"),
      });
      expect(
        await boundary.db.campaign.count({ where: { userId: f.user.id } }),
      ).toBe(0);
      await expect(
        createCampaign(f.user.id, {
          ...input,
          recipientRoles: { [input.recipientIds[0]]: "Researcher" },
        }),
      ).resolves.toMatchObject({ count: 2 });
    },
  );
  it("uses arbitrary saved roles for Free outreach without overrides", async () => {
    const f = await owner();
    const input = await f.input(2);
    for (const [i, id] of input.recipientIds.entries())
      await boundary.db.contact.update({
        where: { id, userId: f.user.id },
        data: { jobRole: `Saved role ${i}` },
      });
    const campaign = await createCampaign(f.user.id, input);
    const sends = await boundary.db.send.findMany({
      where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
    });
    expect(sends.map((s) => s.recipientRole).sort()).toEqual([
      "Saved role 0",
      "Saved role 1",
    ]);
  });
  it("allows distinct Premium overrides without persisting contact changes", async () => {
    const f = await owner(true);
    const input = await f.input(2);
    const campaign = await createCampaign(f.user.id, {
      ...input,
      recipientRoles: Object.fromEntries(
        input.recipientIds.map((id, i) => [id, `Batch role ${i}`]),
      ),
    });
    const sends = await boundary.db.send.findMany({
      where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
    });
    expect(sends.map((s) => s.recipientRole).sort()).toEqual([
      "Batch role 0",
      "Batch role 1",
    ]);
    expect(
      (
        await boundary.db.contact.findMany({ where: { userId: f.user.id } })
      ).map((c) => c.jobRole),
    ).toEqual(["Software Engineer", "Software Engineer"]);
  });
  it.each(["text", "array"])(
    "imports arbitrary roles from %s without a quota",
    async (format) => {
      const f = await owner(true);
      const rows = Array.from({ length: 25 }, (_, i) => ({
        name: "Ada",
        email: `row${i}@example.test`,
        company: "",
        jobRole: `Unique role ${i}`,
      }));
      const input =
        format === "text"
          ? "name,email,jobRole\n" +
            rows
              .map((row) => `${row.name},${row.email},${row.jobRole}`)
              .join("\n")
          : rows;
      expect((await importContacts(input)).ok).toBe(true);
      expect(
        await boundary.db.contact.count({ where: { userId: f.user.id } }),
      ).toBe(25);
    },
  );
  it("keeps approved one-off snapshots eligible after downgrade", async () => {
    const f = await owner(true);
    const input = await f.input(2);
    const campaign = await createCampaign(f.user.id, {
      ...input,
      recipientRoles: {
        [input.recipientIds[0]]: "Designer",
        [input.recipientIds[1]]: "Researcher",
      },
    });
    await downgrade(f.user.id);
    await dispatchUsagePending(f.user.id, async () => {});
    const sends = await boundary.db.send.findMany({
      where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
      orderBy: { id: "asc" },
    });
    expect(sends.map((send) => send.status)).toEqual(["QUEUED", "QUEUED"]);
    await deliverOne(f.user.id, sends[0].id);
    expect(boundary.send).toHaveBeenCalledOnce();
    expect(await listCustomRoles(f.user.id)).toEqual([]);
  });
  it("allows Free repeat preparation using retained receipts and requires explicit resendIds", async () => {
    const f = await owner();
    const input = await f.input();
    const contact = await boundary.db.contact.findFirstOrThrow({
      where: { id: input.recipientIds[0], userId: f.user.id },
    });
    const deliveryKey = randomUUID();
    await withUsageTransaction(boundary.db, f.user.id, (owner) =>
      importUsageEvidence(owner, {
        sourceKey: deliveryKey,
        deliveryKey,
        chargedAt: new Date(Date.now() - 86400000),
        timestampSource: "sentAt",
      }),
    );
    await boundary.db.deliveryReceipt.create({
      data: {
        userId: f.user.id,
        deliveryKey,
        recipientEmail: contact.email,
        createdAt: new Date(Date.now() - 86400000),
        sentAt: new Date(Date.now() - 86400000),
      },
    });
    expect(await addContactToShortlist(contact.id)).toMatchObject({ ok: true });
    expect(
      (
        await saveContact(
          form({
            id: contact.id,
            name: "Edited",
            email: contact.email,
            jobRole: "Software Engineer",
          }),
        )
      ).ok,
    ).toBe(true);
    expect(
      await boundary.db.contact.findFirst({
        where: { id: contact.id, userId: f.user.id },
      }),
    ).toMatchObject({ followUpRequestedAt: expect.any(Date) });
    await expect(createCampaign(f.user.id, input)).rejects.toThrow(
      "All selected contacts were skipped",
    );
    const repeated = { ...input, resendIds: input.recipientIds };
    const campaign = await createCampaign(f.user.id, repeated);
    expect(campaign.count).toBe(1);
    expect(await submitCampaign(repeated)).toMatchObject({ ok: true });
    expect(
      await boundary.db.send.count({
        where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
      }),
    ).toBe(1);
    expect(
      await boundary.db.usageReservation.count({
        where: { userId: f.user.id, status: "RESERVED" },
      }),
    ).toBe(1);
  });
  it.each([false, true])(
    "gates the History shortcut for paid=%s while allowing contact saves",
    async (paid) => {
      const f = await owner(paid);
      const input = await f.input();
      const campaign = await createCampaign(f.user.id, input);
      const send = await boundary.db.send.findFirstOrThrow({
        where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
      });
      await deliverOne(f.user.id, send.id);
      const contact = await boundary.db.contact.findFirstOrThrow({
        where: { id: send.contactId, userId: f.user.id },
      });
      const before = {
        shortlistRemovedAt: new Date(),
        followUpRequestedAt: null,
      };
      await boundary.db.contact.updateMany({
        where: { id: contact.id, userId: f.user.id },
        data: before,
      });
      if (paid) {
        expect(await addToShortlist(send.id)).toMatchObject({ ok: true });
        const prepared = await boundary.db.contact.findFirstOrThrow({
          where: { id: contact.id, userId: f.user.id },
        });
        expect(prepared).toMatchObject({
          shortlistRemovedAt: null,
          followUpRequestedAt: expect.any(Date),
        });
        expect(await addToShortlist(send.id)).toMatchObject({ ok: true });
        expect(
          await boundary.db.contact.findFirstOrThrow({
            where: { id: contact.id, userId: f.user.id },
          }),
        ).toMatchObject({ followUpRequestedAt: prepared.followUpRequestedAt });
        const other = await owner(true);
        expect(await addToShortlist(send.id)).toMatchObject({ ok: false });
        boundary.user.mockResolvedValue({ id: f.user.id });
        boundary.auth.mockResolvedValue({ user: { id: f.user.id } });
        expect(other.user.id).not.toBe(f.user.id);
      } else {
        expect(await addToShortlist(send.id)).toMatchObject({
          ok: false,
          code: "UPGRADE_REQUIRED",
        });
        expect(
          await boundary.db.contact.findFirstOrThrow({
            where: { id: contact.id, userId: f.user.id },
          }),
        ).toMatchObject(before);
      }
      expect(
        await saveContact(
          form({
            name: contact.name,
            email: contact.email,
            jobRole: contact.jobRole ?? "Software Engineer",
          }),
        ),
      ).toMatchObject({ ok: true });
      expect(
        await boundary.db.contact.findFirstOrThrow({
          where: { id: contact.id, userId: f.user.id },
        }),
      ).toMatchObject({
        shortlistRemovedAt: null,
        followUpRequestedAt: expect.any(Date),
      });
    },
  );
  it("locks both reply actions on downgrade, preserves labels, suppresses reminder reads and permits Off", async () => {
    const f = await owner(true);
    const input = await f.input();
    const campaign = await createCampaign(f.user.id, input);
    const send = await boundary.db.send.findFirstOrThrow({
      where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
    });
    await deliverOne(f.user.id, send.id);
    expect((await saveFollowUpDays(7)).ok).toBe(true);
    expect((await markReplied(send.id)).ok).toBe(true);
    await downgrade(f.user.id);
    expect(await undoReply(send.id)).toMatchObject({
      code: "UPGRADE_REQUIRED",
    });
    expect(await markReplied(send.id)).toMatchObject({
      code: "UPGRADE_REQUIRED",
    });
    expect(await addToShortlist(send.id)).toMatchObject({
      ok: false,
      code: "UPGRADE_REQUIRED",
    });
    expect(
      await boundary.db.send.findFirst({
        where: { id: send.id, campaign: { userId: f.user.id } },
      }),
    ).toMatchObject({ status: "REPLIED" });
    expect(await readFollowUps(f.user.id, 7)).toEqual({
      contacts: [],
      total: 0,
    });
    expect(await readFollowUps(f.user.id, 5)).toEqual({
      contacts: [],
      total: 0,
    });
    expect((await saveFollowUpDays(7)).ok).toBe(false);
    expect((await saveFollowUpDays(0)).ok).toBe(true);
    await setGating(boundary.db, false);
    expect((await undoReply(send.id)).ok).toBe(true);
    expect((await markReplied(send.id)).ok).toBe(true);
  });
  it.each(["size", "template", "repeat"])(
    "applies current limits after a %s downgrade, retaining repeat recipients",
    async (requirement) => {
      const f = await owner(true);
      const input = await f.input(requirement === "size" ? 4 : 2);
      if (requirement === "template") {
        const extra = await boundary.db.template.create({
          data: { ...fields, userId: f.user.id },
        });
        input.templateId = extra.id;
      }
      if (requirement === "repeat") {
        const contact = await boundary.db.contact.findFirstOrThrow({
          where: { id: input.recipientIds[0], userId: f.user.id },
        });
        const deliveryKey = randomUUID();
        await withUsageTransaction(boundary.db, f.user.id, (owner) =>
          importUsageEvidence(owner, {
            sourceKey: deliveryKey,
            deliveryKey,
            chargedAt: new Date(Date.now() - 86400000),
            timestampSource: "sentAt",
          }),
        );
        await boundary.db.deliveryReceipt.create({
          data: {
            deliveryKey,
            userId: f.user.id,
            recipientEmail: contact.email,
            createdAt: new Date(Date.now() - 86400000),
            sentAt: new Date(Date.now() - 86400000),
          },
        });
      }
      const campaign = await createCampaign(f.user.id, {
        ...input,
        resendIds: requirement === "repeat" ? input.recipientIds : [],
      });
      const sends = await boundary.db.send.findMany({
        where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
      });
      await downgrade(f.user.id);
      if (requirement === "repeat") {
        const publish = async () => {};
        expect(await dispatchUsagePending(f.user.id, publish)).toBe(
          sends.length,
        );
        expect((await deliverOne(f.user.id, sends[0].id)).outcome).toBe("done");
        expect(boundary.send).toHaveBeenCalledOnce();
        expect(
          await boundary.db.accountNotice.count({
            where: { userId: f.user.id },
          }),
        ).toBe(0);
        expect(
          await boundary.db.send.count({
            where: {
              campaignId: campaign.id,
              campaign: { userId: f.user.id },
              status: "CANCELLED",
            },
          }),
        ).toBe(0);
        return;
      }
      const publish = async () => {
        throw new Error("Forbidden campaign published");
      };
      expect(await dispatchUsagePending(f.user.id, publish)).toBe(0);
      expect((await deliverOne(f.user.id, sends[0].id)).outcome).toBe("done");
      expect(boundary.send).not.toHaveBeenCalled();
      const cancelled = await boundary.db.send.findMany({
        where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
      });
      expect(
        cancelled.every(
          (send) =>
            send.status === "CANCELLED" && send.error?.startsWith("Cancelled:"),
        ),
      ).toBe(true);
      expect(
        await boundary.db.usageReservation.count({
          where: { userId: f.user.id, status: "RELEASED" },
        }),
      ).toBe(sends.length);
      expect(
        await boundary.db.usagePeriod.findMany({
          where: { userId: f.user.id },
          select: { reserved: true, sent: true },
        }),
      ).toEqual(expect.arrayContaining([{ reserved: 0, sent: 0 }]));
    },
  );
  it("suppresses genuinely due reminders after downgrade and allows every configured Paid delay", async () => {
    const f = await owner(true);
    const campaign = await createCampaign(f.user.id, await f.input());
    const send = await boundary.db.send.findFirstOrThrow({
      where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
    });
    await deliverOne(f.user.id, send.id);
    await boundary.db.send.updateMany({
      where: { id: send.id, campaign: { userId: f.user.id } },
      data: { sentAt: new Date(Date.now() - 15 * 86400000) },
    });
    for (const delay of [3, 7, 14]) {
      expect((await saveFollowUpDays(delay)).ok).toBe(true);
      expect((await readFollowUps(f.user.id, delay)).total).toBe(1);
    }
    await downgrade(f.user.id);
    expect(await readFollowUps(f.user.id, 3)).toEqual({
      contacts: [],
      total: 0,
    });
